import Foundation

/// External statistical review, never generated by a model or inferred from timestamps.
/// A caller must independently trust the reviewer. Archive fields cannot add trust.
public struct StatisticalEvidenceReview: Codable, Sendable, Equatable {
    public enum DependenceMethod: String, Codable, Sendable {
        case independentEvents, validatedClusterModel, assumedICC
    }
    public var reviewerID: String
    public var reviewReference: String
    public var cohortDigest: String
    public var verifiedEffectiveSampleSize: Double
    public var dependenceMethod: DependenceMethod
    public var registrationReference: String
    public var registeredAt: Date
    /// IDs must include every attempted policy/expiry/subgroup/sequential look.
    public var registeredTestIDs: [String]
    /// Reviewed one-sided p-values for H0: payout-adjusted expectancy <= 0.
    public var rawPValues: [String: Double]
    public var selectedTestID: String

    public init(reviewerID: String, reviewReference: String, cohortDigest: String,
                verifiedEffectiveSampleSize: Double, dependenceMethod: DependenceMethod,
                registrationReference: String, registeredAt: Date,
                registeredTestIDs: [String], rawPValues: [String: Double], selectedTestID: String) {
        self.reviewerID = reviewerID; self.reviewReference = reviewReference
        self.cohortDigest = cohortDigest; self.verifiedEffectiveSampleSize = verifiedEffectiveSampleSize
        self.dependenceMethod = dependenceMethod; self.registrationReference = registrationReference
        self.registeredAt = registeredAt; self.registeredTestIDs = registeredTestIDs
        self.rawPValues = rawPValues; self.selectedTestID = selectedTestID
    }
}

public struct PromotionEvidenceDecision: Codable, Sendable, Equatable {
    public let statisticalCriteriaMet: Bool
    public let verifiedEffectiveSampleSize: Double?
    public let familyWiseAdjustedPValue: Double?
    public let blockers: [String]
    public var status: String { statisticalCriteriaMet ? "STATISTICAL CRITERIA MET" : "INSUFFICIENT EVIDENCE" }
}

/// Statistical qualification only. This never authorizes a strategy change or entry.
public enum PromotionEvidenceGate {
    public static let minimumEffectiveSampleSize = 250.0
    public static let familyWiseAlpha = 0.05

    public static func assess(nominalSize: Int, candidateBlocks: Int, cohortDigest: String,
                              firstObservationAt: Date?, review: StatisticalEvidenceReview? = nil,
                              trustedReviewerIDs: Set<String> = []) -> PromotionEvidenceDecision {
        guard let review else {
            return PromotionEvidenceDecision(statisticalCriteriaMet: false, verifiedEffectiveSampleSize: nil,
                familyWiseAdjustedPValue: nil,
                blockers: ["Independent/effective sample size has not been verified.",
                    "No reviewed, preregistered complete test family or multiplicity correction."])
        }
        var blockers: [String] = []
        let trusted = trustedReviewerIDs.contains(review.reviewerID) && !review.reviewReference.isEmpty
        if !trusted { blockers.append("Statistical reviewer/reference is not trusted.") }
        let bound = cohortDigest.count == 64 && cohortDigest.allSatisfy(\.isHexDigit)
            && review.cohortDigest == cohortDigest
        if !bound { blockers.append("Review does not match this exact cohort.") }
        let effective = review.verifiedEffectiveSampleSize
        let validCount = nominalSize > 0 && candidateBlocks > 0 && candidateBlocks <= nominalSize
            && effective.isFinite && effective > 0 && effective <= Double(candidateBlocks)
            && effective <= Double(nominalSize) && review.dependenceMethod != .assumedICC
        if !validCount { blockers.append("Effective N is invalid or based only on assumed dependence.") }
        if !effective.isFinite || effective < minimumEffectiveSampleSize {
            blockers.append("Fewer than 250 verified effective events.")
        }
        let prospective = firstObservationAt.map {
            $0.timeIntervalSince1970.isFinite && review.registeredAt.timeIntervalSince1970.isFinite
                && review.registeredAt <= $0
        } ?? false
        if !prospective || review.registrationReference.isEmpty {
            blockers.append("The test family was not registered before the evaluated observations.")
        }
        let ids = Set(review.registeredTestIDs)
        let completeFamily = !ids.isEmpty && ids.count == review.registeredTestIDs.count
            && ids.allSatisfy { !$0.isEmpty } && ids == Set(review.rawPValues.keys)
            && ids.contains(review.selectedTestID)
            && review.rawPValues.values.allSatisfy { $0.isFinite && (0...1).contains($0) }
        var corrected: Double?
        if completeFamily, let p = review.rawPValues[review.selectedTestID] {
            // Bonferroni controls the registered family without assuming tests independent.
            let adjusted = min(1, p * Double(ids.count))
            corrected = adjusted
            if adjusted >= familyWiseAlpha { blockers.append("Family-wise corrected significance does not clear alpha 0.05.") }
        } else { blockers.append("Registered tests/looks are missing, duplicated or have invalid p-values.") }
        return PromotionEvidenceDecision(statisticalCriteriaMet: blockers.isEmpty,
            verifiedEffectiveSampleSize: trusted && bound && validCount ? effective : nil,
            familyWiseAdjustedPValue: trusted && bound && validCount && prospective && completeFamily ? corrected : nil,
            blockers: blockers)
    }
}
